class ParameterHandler:
    """Handles parameter processing for a vertex.

    This class extracts the parameter-processing logic that used to live inside
    ``Vertex.build_params`` so that it can be tested independently. It knows how
    to turn a vertex's edges and template fields into a dictionary of parameters.
    """

    def __init__(self, vertex: Vertex, storage_service: StorageService) -> None:
        self.vertex = vertex
        self.graph = vertex.graph
        self.storage_service = storage_service
        # Only the dict-valued entries of the template describe actual fields.
        self.template_dict: dict[str, dict] = {
            key: value
            for key, value in vertex.data["node"]["template"].items()
            if isinstance(value, dict)
        }
        self.load_from_db_fields: list[str] = []

    def process_edge_parameters(self, edges: list) -> dict:
        """Build the params dict coming from the edges connected to the vertex.

        Edges without a ``target_param`` are skipped.
        """
        params: dict = {}
        for edge in edges:
            if not hasattr(edge, "target_param"):
                continue
            params = self._set_params_from_normal_edge(params, edge)
        return params

    def _set_params_from_normal_edge(self, params: dict, edge: Edge) -> dict:
        param_key = edge.target_param

        # If the param_key is in the template_dict and the edge.target_id is the current node
        # We check this to make sure params with the same name but different target_id
        # don't get overwritten
        if param_key in self.template_dict and edge.target_id == self.vertex.id:
            field = self.template_dict[param_key]
            if field.get("list"):
                if param_key not in params:
                    params[param_key] = []
                params[param_key].append(self.graph.get_vertex(edge.source_id))
            else:
                params[param_key] = self.process_non_list_edge_param(field, edge)
        elif param_key in self.vertex.output_names:
            params[param_key] = self.graph.get_vertex(edge.source_id)
        return params

    def process_non_list_edge_param(self, field: dict, edge: Edge) -> Any:
        """Resolve the value for a non-list edge parameter.

        For empty or non-dict field values the source vertex is returned directly.
        For single-entry dict field values a new dict mapping that key to the
        source vertex is returned.
        """
        source_vertex = self.graph.get_vertex(edge.source_id)
        param_value = field.get("value")
        if isinstance(param_value, dict) and len(param_value) == 1:
            return {key: source_vertex for key in param_value}
        return source_vertex

    def should_skip_field(self, field_name: str, field: dict, params: dict) -> bool:
        """Return whether the given field should be skipped during processing."""
        if field_name in params or field_name == "_type":
            return True
        return not field["show"]

